/// Thread-safe quota tracker.
30→pub struct QuotaManager {
    tier: Arc<RwLock<QuotaTier>>,
    queries_today: AtomicU32,
    last_reset: Arc<RwLock<DateTime<Utc>>>,
}

impl QuotaManager {
    pub fn new(tier: QuotaTier) -> Self {
